tool_and_message_events.command:
/bin/bash -lc 'audit_dir=$(mktemp -d "$PWD/.desk-review.XXXXXX") &&
trap '"'python3 -c \"import shutil,sys; shutil.rmtree(sys.argv[1])\" \""'$audit_dir"'"' EXIT &&
cp -R release/. \""'$audit_dir/" &&
cd "$audit_dir" &&
npm_config_cache="$audit_dir/.npm-cache" npm install --offline --ignore-scripts --no-audit --no-fund ../vendor/hono-4.13.19.tgz &&
npm_config_cache="$audit_dir/.npm-cache" npm test &&
node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import app from './app.mjs';

const {version} = JSON.parse(readFileSync('node_modules/hono/package.json', 'utf8'));
assert.equal(version, '4.13.19');
console.log({hono: version, node: process.version});

const checks = [
  ['valid record', 'a7', true, 200, {id: 'a7', title: 'Harbor'}, 'dispatch,session,read'],
  ['no session', 'a7', false, 401, {error: 'sign_in'}, 'dispatch,session'],
  ['missing record', 'missing-card', true, 404, {error: 'not_found'}, 'dispatch,session,read'],
  ['invalid record', 'b4', true, 502, {error: 'invalid_record'}, 'dispatch,session,read,error'],
  ['admission before record lookup', 'b4', false, 401, {error: 'sign_in'}, 'dispatch,session'],
];

for (const [name, id, signedIn, status, body, steps] of checks) {
  const response = await app.request(new Request('http://localhost/desk/' + id, {
    headers: signedIn ? {'x-shift': 'day'} : {},
  }));
  assert(response instanceof Response);
  assert.equal(response.status, status);
  assert.match(response.headers.get('content-type') ?? '', /"'^application'"\\/json\\b/);
  assert.deepEqual(await response.json(), body);
  assert.equal(response.headers.get('x-desk-steps'), steps);
  console.log(name, status, JSON.stringify(body), steps);
}
NODE"

